// Turn the uploaded file into a base64 data URI for the Mistral OCR API.
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const bin = item.binary || {};
  const key = Object.keys(bin)[0];
  if (!key) throw new Error('No binary file on the incoming item.');
  const b = bin[key];
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  const mime = b.mimeType || 'application/pdf';
  out.push({ json: {
    fileName: b.fileName || 'document',
    mimeType: mime,
    dataUri: 'data:' + mime + ';base64,' + buf.toString('base64')
  }});
}
return out;

/* ============ SHARED ============ */

var ORDINAL_WORDS = {
  one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10,
  eleven:11, twelve:12, thirteen:13, fourteen:14, fifteen:15, sixteen:16,
  seventeen:17, eighteen:18, nineteen:19, twenty:20,
  first:1, second:2, third:3, fourth:4, fifth:5, sixth:6, seventh:7, eighth:8,
  ninth:9, tenth:10
};
var ORD_WORD_RE = Object.keys(ORDINAL_WORDS).join('|');

var ROMAN_RE = /^[ivxlcdm]+$/i;

function romanToInt(s) {
  var m = { i:1, v:5, x:10, l:50, c:100, d:500, m:1000 }, t = 0, p = 0, i;
  s = String(s).toLowerCase();
  for (i = s.length - 1; i >= 0; i--) {
    var v = m[s[i]] || 0;
    t += v < p ? -v : v;
    p = Math.max(p, v);
  }
  return t;
}

/* numeric value of a marker token, for monotonicity / TOC detection */
function markerValue(tok) {
  if (tok == null) return NaN;
  tok = String(tok).trim();
  var m = tok.match(/^(\d+)/);
  if (m) return parseInt(m[1], 10);
  if (ROMAN_RE.test(tok)) return romanToInt(tok);
  var w = ORDINAL_WORDS[tok.toLowerCase()];
  return w == null ? NaN : w;
}

/* Units / measurement tails that must never open a provision. */
var UNIT_TAIL = '(?:mm|cm|km|kg|kV|kA|kW|MW|MPa|kPa|Hz|MHz|GHz|ms|min|sec|hrs?|%|per\\s?cent|°C|℃|m[²³]?\\b|ft|in\\b|lbs?\\b)';

/* Lines that are pure furniture. */
var NOISE_RES = [
  /^\s*[-–—~]{1,3}\s*\d{1,4}\s*[-–—~]{1,3}\s*$/,          // - 12 -
  /^\s*(?:page\s+)?\d{1,4}\s*(?:of|\/)\s*\d{1,4}\s*$/i,    // 3 of 8 · Page 3/8
  /^\s*page\s+\d{1,4}\s*$/i,
  /^\s*\d{1,4}\s*$/,                                        // bare page number
  /^\s*[ivxlcdm]{1,6}\s*$/i,                                // roman page number
  /^.{1,80}[.·]{4,}\s*\d{1,4}\s*$/,                         // TOC dotted leader
  /^\s*_{3,}\s*$/,
  /^\s*(?:\[\d{1,6}\]|\d{1,6})(?:\s+(?:\[\d{1,6}\]|\d{1,6}))?\s*$/,   // "[283] 7" · "44 [283]"
  /^\s*[A-Z .]{0,40}\s*\d{1,4}\s*\[\d{1,6}\]\s*$/,
  /^\s*\[?\s*(?:this page (?:is )?(?:intentionally )?(?:left )?blank)\s*\]?\s*$/i,
  /^\s*(?:unofficial|informal)\s+translation\s*$/i,
  /^\s*compilation\s+no\.?\s*\d+\s*$/i,
  /^\s*registered\s*:\s*\d/i,
  /^\s*\d{0,3}\s*OJ\s+(?:No\.|L\b|C\b)/,                                   // EU OJ footnote
  /^\s*Notice of the making of this Statutory Instrument was published/i,
  /^\s*(?:GIVEN under my hand|Given under my (?:hand|Official Seal))/i,
  /^\s*THE\s+GAZETTE\s+OF\s+INDIA\b/i,
  /^\s*\[?\s*PART\s+[IVX]+\s*[\u2014-]{0,2}\s*SEC\.?[^\]]*\]?\s*$/i,      // [PART II-SEC. 3(ii)]
  /^\s*\u0939\u093F|^\s*\[\s*\u092D\u093E\u0917/,                            // Hindi gazette banner
  /^\s*\(?(?:Published|To be published) in the Gazette/i
];

/* Dialect-scoped strippers: applied to a whole line, in place. */
var STRIPPERS = {
  /* Hong Kong inline source notes: (Amended 12 of 1999 s. 3) */
  hk_source: /\s*\((?:Amended|Added|Replaced|Repealed|Format changes)[^()]*(?:\([^()]*\)[^()]*)*\)\s*$/g,
  /* UK legislation.gov.uk textual-amendment markers: [F1 …] */
  uk_fmark: /\[?F\d{1,4}\]?/g,
  /* Ireland eISB markers: F5[ … ]F5 */
  ie_fmark: /F\d{1,4}\[|\]F\d{1,4}/g,
  /* South Africa consolidation editorial notes */
  za_edit: /\[[^\]]*?(?:substituted|inserted|added|deleted|amended|repealed|commencement|Sub-s\.|Para\.)[^\]]*?\]/gi,
  /* India / SEBI / RBI superscript footnote caller fused to a bracket: 3[ … ] */
  in_bracket_open: /(^|[\s(])(\d{1,3})\[/g,
  in_omitted: /\*{3,}/g,
  /* Editorial asterisk / hash prefixes (HK not-yet-in-operation) */
  hk_flag: /^\s*[*#]+\s*/
};

/* Non-boundary content markers — kept inside `contenu`, used only to
   disambiguate and to repair OCR line merges. */
var RE_SUBSEC   = /^\s*\((\d{1,3}[A-Z]{0,2})\)\s+/;
var RE_PARA_A   = /^\s*\(([a-z]{1,3})\)\s+/;
var RE_PARA_ROM = /^\s*\(([ivxlcdm]{1,8})\)\s+/;
var RE_PARA_CAP = /^\s*\(([A-Z]{1,3})\)\s+/;
var RE_IE_DEG   = /^\s*(\d{1,2})\s*[\u00B0\u00BA\u02DA]\s*(.*)$/;   // Irish 1° 2° 3°

/* Special content blocks (tagged, never boundaries). */
var RE_PROVISO     = /^\s*Provided\s+(?:that|further|also|always)\b/i;
var RE_EXPLANATION = /^\s*Explanation\s*(\d+)?\s*[.:\u2014-]/i;
var RE_ILLUSTR     = /^\s*Illustrations?\s*[.:\u2014-]?\s*$/i;
var RE_NOTE_AU     = /^\s*Note\s*(\d+)?\s*:/i;
var RE_PENALTY_AU  = /^\s*(?:Maximum\s+)?Penalt(?:y|ies)\s*:/i;
var RE_REPEALED    = /^\s*\(?(Repealed|Omitted|Deleted|Not yet in operation)\)?\s*\.?\s*$/i;

/* TOC entry / exit. */
var RE_TOC_HEAD = /^\s*(?:ARRANGEMENT\s+OF\s+(?:SECTIONS|CLAUSES|PARAGRAPHS|RULES|REGULATIONS|ARTICLES|ORDERS)|TABLE\s+OF\s+(?:PROVISIONS|CONTENTS)|CONTENTS|INDEX\s+OF\s+SECTIONS|SECTIONS)\s*$/i;
var RE_TOC_EXIT = /(?:BE\s+IT\s+ENACTED|ENACTED\s+by|^\s*An?\s+ACT\s+to\b|^\s*WHEREAS\b|^\s*PREAMBLE\b|in\s+exercise\s+of\s+the\s+(?:powers|functions)\s+conferred|hereby\s+(?:make|makes|order|orders|prescribe|prescribes|issue|issues)\b|Now,?\s+therefore)/i;

/* Front matter that precedes the operative body. */
var RE_LONG_TITLE = /^\s*An?\s+(?:Act|Ordinance|Law|Bill)\s+to\b/i;
var RE_ENACTING   = /^\s*(?:BE\s+IT\s+ENACTED|ENACTED\s+by|Now,?\s+therefore|The\s+Parliament\s+of|Do\s+hereby\s+(?:issue|decree|promulgate))/i;
var RE_PREAMBLE   = /^\s*(?:PREAMBLE|WHEREAS\b|Having\s+reviewed\b|Having\s+perused\b)/i;

function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function isNoise(line) {
  for (var i = 0; i < NOISE_RES.length; i++) if (NOISE_RES[i].test(line)) return true;
  return false;
}

/* ============ STAGE 1 · clean ============ */

/* Clean text: normalise, de-markdown, drop furniture, optional dewrap,
   TOC guard. Dialect-agnostic — nothing here needs to know the country. */

function stripMarkdown(t) {
  return t
    .replace(/^\s{0,3}#{1,6}\s+/gm, '')          // ATX headings
    .replace(/\*\*(.+?)\*\*/g, '$1')             // bold
    .replace(/__(.+?)__/g, '$1')
    .replace(/(^|[^*])\*(?!\s)([^*\n]+?)\*(?!\*)/g, '$1$2')   // italic
    .replace(/^\s{0,3}>\s?/gm, '')               // block quotes
    /* Mistral renders provision items as markdown bullets: "- (a) ...", "-(a) ...",
       "* (b) ...", escaped "\\- (c) ...", nested "- - (d) ...". Strip repeatedly so
       nested markers unwind; an em dash at line start is real text and is kept. */
    .replace(/^((?:[ \t]*\\?[-*+\u2022\u00B7](?:[ \t]+|(?=\()))+)/gm, '')
    .replace(/^\s*\|\s*-+[\s|:-]*\|\s*$/gm, '')  // md table rules
    .replace(/\\\[|\\\]|\\\(|\\\)/g, '');        // stray latex delimiters
}

function normalize(text, opts) {
  opts = opts || {};
  var t = String(text == null ? '' : text);

  if (typeof t.normalize === 'function') { try { t = t.normalize('NFKC'); } catch (e) {} }

  t = t
    .replace(/\r\n?/g, '\n')
    .replace(/\f/g, '\n')
    .replace(/[\u200B-\u200D\uFEFF\u00AD]/g, '')          // zero-width, soft hyphen
    .replace(/[\u00A0\u2007\u202F\u2009\u2002-\u2006]/g, ' ')
    .replace(/[\u2018\u2019\u2032]/g, "'")
    .replace(/[\u201C\u201D\u2033]/g, '"')
    .replace(/[\u2010\u2011\u2012\u2013\u2015\u2212]/g, '\u2014')  // dashes -> em dash
    .replace(/\u2014{2,}/g, '\u2014')
    .replace(/\u2026/g, '...');

  if (opts.stripMarkdown !== false) t = stripMarkdown(t);

  t = t.replace(/[ \t]+/g, ' ').replace(/ +$/gm, '');
  return t;
}

/* Repeated running headers / footers: any identical line seen >= n times. */
function dropRepeatedLines(lines, minRepeat) {
  minRepeat = minRepeat || 4;
  var count = Object.create(null), i, k;
  for (i = 0; i < lines.length; i++) {
    k = lines[i].trim();
    if (k.length >= 4 && k.length <= 120) count[k] = (count[k] || 0) + 1;
  }
  var out = [];
  for (i = 0; i < lines.length; i++) {
    k = lines[i].trim();
    if (k && count[k] >= minRepeat && !/[.;:]$/.test(k)) continue;
    out.push(lines[i]);
  }
  return out;
}

/* Re-join hard-wrapped extractions (pdftotext). Mistral output is reflowed
   already, so this is opt-in. */
/* A real enumeration marker: digits, a letter in parens, or a roman numeral.
   NOT any short word ending in a period ("work." is prose, not a marker). */
var BARE_MARKER = /^\s*(?:\(\s*(?:\d{1,3}[A-Z]{0,2}|[a-z]{1,3}|[ivxlcdm]{1,6}|[A-Z]{1,3})\s*\)|\d{1,4}[A-Z]{0,3}\.|\d{1,3}\)|[a-z]\))\s*$/;
var MARKER_START = /^\s*(?:\(\s*(?:\d{1,3}[A-Z]{0,2}|[a-z]{1,3}|[ivxlcdm]{1,6}|[A-Z]{1,3})\s*\)|\d{1,4}[A-Z]{0,3}\.|\d{1,3}\)|[a-z]\))\s/;
var CAPS_HEADING = /^[A-Z][A-Z0-9 \-'(),.\u2014]{5,}$/;

function dewrap(t) {
  var lines = t.split('\n'), out = [], buf = '';
  function flush() { if (buf) { out.push(buf); buf = ''; } }
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i];
    if (!ln.trim()) {
      if (BARE_MARKER.test(buf)) continue;          // a lone marker waits for its text
      flush(); out.push(''); continue;
    }
    var startsStructure =
      /^\s*(?:PART|CHAPTER|SCHEDULE|ANNEX|ORDER|Division|Subdivision|Article|Section|Rule|Regulation)\b/i.test(ln) ||
      MARKER_START.test(ln) || BARE_MARKER.test(ln) ||
      /^\s*\[\d+\]/.test(ln) ||
      CAPS_HEADING.test(ln.trim());
    if (!buf) { buf = ln.trim(); continue; }
    if (BARE_MARKER.test(buf)) { buf = buf.trim() + ' ' + ln.trim(); continue; }
    if (startsStructure || /[.;:]$/.test(buf) || CAPS_HEADING.test(buf.trim())) { flush(); buf = ln.trim(); }
    else buf = buf.replace(/-$/, '') + (/-$/.test(buf) ? '' : ' ') + ln.trim();
  }
  flush();
  return out.join('\n');
}


/* TOC guard (Vol. I §6.1). Enter on an explicit header; exit on the first
   backwards jump in top-level numbering, on an enacting formula, or on a
   heading immediately followed by a subsection marker. */
function stripTOC(lines) {
  var out = [], inToc = false, high = 0, tocStart = -1, i;
  for (i = 0; i < lines.length; i++) {
    var ln = lines[i], t = ln.trim();

    if (!inToc && RE_TOC_HEAD.test(t)) { inToc = true; high = 0; tocStart = i; continue; }

    if (inToc) {
      if (!t) continue;
      if (RE_TOC_EXIT.test(t)) { inToc = false; out.push(ln); continue; }

      var m = t.match(/^(\d{1,4})[A-Z]{0,3}[.\s]/);
      if (m) {
        var v = markerValue(m[1]);
        if (!isNaN(v)) {
          if (v < high) { inToc = false; out.push(ln); continue; }   // backwards jump = body
          high = Math.max(high, v);
        }
      }
      /* a heading immediately followed by a subsection marker is body, not TOC */
      var nxt = (lines[i + 1] || '').trim();
      if (m && (RE_SUBSEC.test(nxt) || /^\(\d+\)/.test(nxt))) { inToc = false; out.push(ln); continue; }
      continue;                                     // swallow TOC line
    }
    out.push(ln);
  }
  /* if we never found an exit the whole tail got eaten — bail out safely */
  if (inToc && tocStart >= 0) return lines.slice(0);
  return out;
}

function cleanText(input, opts) {
  opts = opts || {};
  var t = normalize(input, opts);

  var lines = t.split('\n');
  if (opts.dropRepeated !== false) lines = dropRepeatedLines(lines, opts.minRepeat || 4);
  lines = lines.filter(function (l) { return !isNoise(l); });
  if (opts.skipTOC !== false) lines = stripTOC(lines);
  if (opts.dewrap) lines = dewrap(lines.join('\n')).split('\n');

  /* collapse >2 blank lines */
  var out = [], blanks = 0;
  for (var i = 0; i < lines.length; i++) {
    if (!lines[i].trim()) { blanks++; if (blanks > 1) continue; }
    else blanks = 0;
    out.push(lines[i].replace(/\s+$/, ''));
  }
  while (out.length && !out[0].trim()) out.shift();
  while (out.length && !out[out.length - 1].trim()) out.pop();
  return out.join('\n');
}

/* Input adapter — same contract as the Chinese parser. */
function recordsFromText(input) {
  if (input == null) return '';
  if (typeof input === 'string') return input;
  if (Array.isArray(input)) {
    return input.map(function (p) {
      if (typeof p === 'string') return p;
      return p.markdown || p.text || p.extractedText || p.content || '';
    }).join('\n\n');
  }
  if (typeof input === 'object') {
    if (typeof input.extractedText === 'string') return input.extractedText;
    if (typeof input.text === 'string') return input.text;
    if (typeof input.markdown === 'string') return input.markdown;
    if (Array.isArray(input.pages)) return recordsFromText(input.pages);
  }
  return String(input);
}

/* ============ STAGE 2 · detect + blocks ============ */

/* Detect doc_class, then jurisdiction dialect, apply dialect strippers,
   split zones, and run Pass 1 into structural blocks. */

/* ---------- Stage 2a: document class ---------- */

var CLASS_SIGNALS = [
  // standards
  { cls: 'standard',    w: 8, re: /^\s*2\s+Normative references\s*$/im },
  { cls: 'standard',    w: 7, re: /^\s*Annex\s+[A-Z]{1,2}\s*\(\s*(?:normative|informative)\s*\)/im },
  { cls: 'standard',    w: 4, re: /^\s*(?:1\s+Scope|3\s+Terms and definitions)\s*$/im },
  { cls: 'standard',    w: 3, re: /\b(?:BS\s+EN|AS\/NZS|SANS|IS\s*\d{3,5}|UAE\.S|ISO\/IEC|ISO\s+\d{3,5})\b/ },
  // judgments
  { cls: 'judgment',    w: 9, re: /\[\d{4}\]\s+(?:UKSC|UKHL|UKPC|EWCA\s+(?:Civ|Crim)|EWHC|IESC|IECA|IEHC|HKCFA|HKCA|HKCFI|HCA|FCAFC|FCA|ZACC|ZASCA|INSC)\b/ },
  { cls: 'judgment',    w: 5, re: /(?:^|\n)\s*\[\d{1,3}\]\s+[A-Z][^\n]{20,}(?:\n[\s\S]{0,400}?){0,2}\n\s*\[\d{1,3}\]\s+[A-Z]/ },
  { cls: 'judgment',    w: 4, re: /\bJUDGMENT\b|\bbefore\s*:\s*(?:Lord|Lady|The Hon)/i },
  // court rules
  { cls: 'court_rules', w: 7, re: /^\s*ORDER\s+(?:[IVXLCDM]+|\d+)\b/im },
  { cls: 'court_rules', w: 6, re: /\bPRACTICE\s+DIRECTION\b|\bCIVIL\s+PROCEDURE\s+RULES\b|\bRules of the (?:Superior Courts|High Court|Supreme Court)\b/i },
  { cls: 'court_rules', w: 4, re: /^\s*\d{1,3}\.\d{1,3}\s+[A-Z]/m },
  // regulatory
  { cls: 'regulatory',  w: 8, re: /^\s*[A-Z]{2,6}\s+\d+[A-Z]?(?:\.\d+[A-Z]?){1,3}\s+(?:R|E|G|D|P|C|UK|EU)\b/m },
  { cls: 'regulatory',  w: 7, re: /\bPrudential\s+(?:Standard|Practice Guide)\s+[A-Z]{2,3}[SG]\s*\d+|^\s*RG\s+\d+\.\d+/im },
  { cls: 'regulatory',  w: 6, re: /\bMASTER\s+(?:CIRCULAR|DIRECTION)\b|\bSEBI\/[A-Z0-9\/]+|\bRBI\/\d{4}-\d{2}\b/i },
  { cls: 'regulatory',  w: 4, re: /\b(?:Handbook|Rulebook|Sourcebook|Conduct Standard|Circular No\.)\b/i },
  // constitution
  { cls: 'constitution',w: 8, re: /\bCONSTITUTION\s+OF\b|\bBUNREACHT\s+NA\s+H[EÉ]IREANN\b|\bBASIC\s+LAW\b/i },
  { cls: 'constitution',w: 4, re: /\bFUNDAMENTAL\s+RIGHTS\b|\bDIRECTIVE\s+PRINCIPLES\b|\bBILL\s+OF\s+RIGHTS\b/i },
  // subsidiary
  { cls: 'subsidiary',  w: 6, re: /\bG\.?\s?S\.?\s?R\.?\s*\d+\s*\(E\)|\bS\.?\s?O\.?\s*\d+\s*\(E\)/ },
  { cls: 'subsidiary',  w: 6, re: /\bS\.I\.\s*No\.\s*\d+\s*of\s*\d{4}|\b\d{4}\s+No\.\s*\d+\b|\bL\.N\.\s*\d+\s+of\s+\d{4}/i },
  { cls: 'subsidiary',  w: 5, re: /\bGN\s?R?\.?\s*\d+,?\s*G\.?\s*\d+\b|\bGovernment Notice\b/i },
  { cls: 'subsidiary',  w: 5, re: /\b(?:Regulations|Rules|Order)\s+\d{4}\s*$/im },
  { cls: 'subsidiary',  w: 4, re: /\bCabinet\s+(?:Resolution|Decision)\s+No\.|\bMinisterial\s+(?:Resolution|Decision)\s+No\.|\bExecutive\s+Regulations?\b/i }
];

function classifyDoc(text) {
  var head = text.split('\n').slice(0, 160).join('\n');
  var scores = { primary: 1 }, i, s;
  for (i = 0; i < CLASS_SIGNALS.length; i++) {
    s = CLASS_SIGNALS[i];
    if (s.re.test(head) || (s.w >= 7 && s.re.test(text.slice(0, 20000)))) {
      scores[s.cls] = (scores[s.cls] || 0) + s.w;
    }
  }
  var best = 'primary', bv = 0;
  for (var k in scores) if (scores[k] > bv) { bv = scores[k]; best = k; }
  return { doc_class: best, scores: scores };
}

/* ---------- Stage 2b: jurisdiction dialect ---------- */

var DIALECT_SIGNALS = [
  { d: 'HK', w: 6, re: /\((?:Amended|Added|Replaced)\s+\d+\s+of\s+\d{4}/ },
  { d: 'HK', w: 4, re: /\bCap\.\s*\d+[A-Z]?\b|\bL\.N\.\s*\d+\s+of\s+\d{4}/ },
  { d: 'HK', w: 3, re: /[\u4e00-\u9fff]{4,}/ },
  { d: 'UK', w: 5, re: /\[F\d+|Textual Amendments|Modifications etc\./ },
  { d: 'UK', w: 4, re: /\bHer Majesty|His Majesty|King's most Excellent Majesty|Queen's most Excellent Majesty\b/ },
  { d: 'UK', w: 3, re: /\bStatutory Instruments?\b|\bSI\s+\d{4}\/\d+\b/ },
  { d: 'IE', w: 6, re: /F\d+\[|\]F\d+|\bOireachtas\b|\bS\.I\.\s*No\.\s*\d+\s*of\s*\d{4}/i },
  { d: 'IE', w: 4, re: /^\s*Number\s+\d+\s+of\s+\d{4}\s*$/m },
  { d: 'AU', w: 6, re: /\bCompilation No\.|\bFederal Register of Legislation\b|\bpenalty units\b/i },
  { d: 'AU', w: 4, re: /^\s*Note\s*\d*\s*:/m },
  { d: 'IN', w: 6, re: /\bGazette of India\b|\bIndia Code\b/i },
  { d: 'IN', w: 6, re: /\[\s*PART\s+[IVX]+\s*[\u2014-]\s*SEC\.|MINISTRY OF (?:ENVIRONMENT|LAW|FINANCE|HOME AFFAIRS)|\bNew Delhi, the\b/i },
  { d: 'IN', w: 5, re: /^\s*\d+\.\s+[A-Z][^\n]{3,80}\.\s*[\u2014-]{1,2}\s*\(1\)/m },
  { d: 'IN', w: 5, re: /\bExplanation\s*\d*\s*[.\u2014]|^\s*Illustrations?\s*$/im },
  { d: 'IN', w: 4, re: /\b(?:Central Pollution Control Board|State Pollution Control Board|Central Government|Adhiniyam|Sanhita)\b/ },
  { d: 'NG', w: 6, re: /\bLaws of the Federation of Nigeria\b|\bNational Assembly of the Federal Republic of Nigeria\b|\bCap\.\s*[A-Z]\d+\b/i },
  { d: 'ZA', w: 6, re: /\bGOVERNMENT GAZETTE\b|\bStaatskoerant\b|\[\s*(?:Sub-)?s\.?\s*\d[^\]]*substituted by/i },
  { d: 'ZA', w: 4, re: /unless the context otherwise indicates\s*\u2014|\bRepublic of South Africa\b/i },
  { d: 'AE', w: 7, re: /\bFederal Decree-Law\b|\bUnofficial translation\b|\boriginal Arabic text\b|\bUnited Arab Emirates\b/i },
  { d: 'AE', w: 5, re: new RegExp('^\\s*(?:Chapter|Part|Section)\\s+(?:' + ORD_WORD_RE + ')\\b', 'im') },
  { d: 'AE', w: 4, re: /\bDIFC\b|\bADGM\b|\bAbu Dhabi Global Market\b|\bDubai International Financial Centre\b/ }
];

function classifyDialect(text) {
  var probe = text.slice(0, 40000), scores = {}, i;
  for (i = 0; i < DIALECT_SIGNALS.length; i++) {
    if (DIALECT_SIGNALS[i].re.test(probe)) {
      scores[DIALECT_SIGNALS[i].d] = (scores[DIALECT_SIGNALS[i].d] || 0) + DIALECT_SIGNALS[i].w;
    }
  }
  var best = null, bv = 0;
  for (var k in scores) if (scores[k] > bv) { bv = scores[k]; best = k; }
  return { dialect: best, scores: scores };
}

/* Vol. I 3.1: for subsidiary legislation the leaf unit is set by the instrument
   title, not the jurisdiction. Regulations -> regulation, Order -> article,
   Rules -> rule. */
function detectLeafUnit(text, doc_class) {
  var head = text.split('\n').slice(0, 60).join('\n');
  var m = head.match(/^[^\n]*\b(REGULATIONS|RULES|ORDER)\s+(?:19|20)\d{2}\b/m);
  if (!m) m = head.match(/\b(Regulations|Rules|Order)\s+(?:19|20)\d{2}\s*$/m);
  if (!m) m = head.match(/\b(Regulations|Rules|Order)\s+(?:19|20)\d{2}\b/);
  if (!m) return null;
  var w = m[1].toLowerCase();
  if (w === 'regulations') return 'Regulation';
  if (w === 'rules') return 'Rule';
  if (w === 'order') return 'Article';
  return null;
}

/* class + dialect -> family */
function pickFamily(doc_class, dialect, text) {
  if (doc_class === 'standard')    return 'en_standards_clause';
  if (doc_class === 'judgment')    return 'en_judgment';
  if (doc_class === 'regulatory')  return 'en_regulatory';
  if (doc_class === 'court_rules') return 'en_order_rule';
  if (doc_class === 'constitution') return 'en_constitution';
  if (dialect === 'AE') return 'en_gulf_article';
  if (dialect === 'ZA') return 'en_sa_gazette';
  if (dialect === 'IN' || dialect === 'NG') return 'en_commonwealth_legacy';
  if (dialect === 'UK' || dialect === 'IE' || dialect === 'AU' || dialect === 'HK') return 'en_westminster';
  /* structural fallback — Vol. I 4: tie-break to en_westminster, the safe superset */
  var arts = (text.match(/^\s*Article\s*[\(\d]/gim) || []).length;
  var secs = (text.match(/^\s*\d{1,4}[A-Z]{0,3}\.?\s+[A-Z]/gm) || []).length;
  var groups = (text.match(/^\s*(?:PART|CHAPTER|SCHEDULE|Division)\b/gim) || []).length;
  if (arts >= 3 && arts > secs) return 'en_gulf_article';
  if (secs >= 3 || (secs >= 1 && groups >= 1)) return 'en_westminster';
  if (doc_class === 'primary' || doc_class === 'subsidiary') return 'en_westminster';
  return 'generic';
}

/* ---------- Stage 2c: dialect strippers ---------- */

function applyStrippers(text, dialect, doc_class) {
  var lines = text.split('\n'), i, l;
  for (i = 0; i < lines.length; i++) {
    l = lines[i];
    if (dialect === 'HK') { l = l.replace(STRIPPERS.hk_flag, '').replace(STRIPPERS.hk_source, ''); }
    if (dialect === 'UK') { l = l.replace(STRIPPERS.uk_fmark, ''); }
    if (dialect === 'IE') { l = l.replace(STRIPPERS.ie_fmark, ''); }
    if (dialect === 'ZA') { l = l.replace(STRIPPERS.za_edit, ''); }
    if (dialect === 'IN' || dialect === 'NG' || doc_class === 'regulatory') {
      l = l.replace(STRIPPERS.in_bracket_open, '$1').replace(/\]/g, function (m, off, s) {
        return /\[/.test(s.slice(0, off)) ? '' : m;
      });
      l = l.replace(STRIPPERS.in_omitted, '');
    }
    lines[i] = l.replace(/\s{2,}/g, ' ').replace(/\s+$/, '');
  }
  return lines.join('\n');
}

