/* Reject a candidate leaf whose "title" is really a measurement, a date,
   or a continuation of prose. */
var UNIT_RE  = new RegExp('^\\d[\\d.,\\s\u00D7xX]*' + UNIT_TAIL, 'i');
var BARE_UNIT_RE = /^(?:mm|cm|km|kg|kV|kA|kW|MW|MPa|kPa|Hz|MHz|GHz|%|\u00B0C|\u2103)\b/i;
var DATE_RE  = /^(?:January|February|March|April|May|June|July|August|September|October|November|December)\b/i;
/* A schedule/annex heading stands alone on its line; a cross-reference does not. */
function isStandaloneHeading(line) {
  var t = line.trim();
  if (t.length > 90) return false;
  if (/[,;]$/.test(t)) return false;
  var kw = t.match(/^(?:THE\s+)?([A-Za-z]+)/);
  if (!kw) return false;
  if (kw[1] === kw[1].toUpperCase()) return true;          // SCHEDULE 1
  return /^(?:THE\s+)?[A-Za-z]+\s*(?:\d+|[IVXLCDM]+|[A-Z])?\s*[:.\u2014-]?\s*$/.test(t);
}

function looksLikeNoiseTitle(title) {
  if (!title) return false;
  var t = title.trim();
  if (UNIT_RE.test(t) || BARE_UNIT_RE.test(t)) return true;
  if (DATE_RE.test(t)) return true;
  if (/^(?:of|to|in|on|at|by|for|and|or|the|a|an)\b/.test(t)) return true;   // mid-sentence
  return false;
}

/* Pass 1 — text -> structural blocks. */
function toBlocks(text, family, opts) {
  opts = opts || {};
  var leafUnit = opts.leafUnit || null;
  var cfg = FAMILIES[family] || FAMILIES.generic;
  var lines = text.split('\n');
  var blocks = [], cur = null, zone = 'body', zoneKey = '', zoneSeq = 0;
  var stack = {}, frontDone = !opts.skipFrontMatter, i, j;
  var inIllustration = false, sawArticle = false;

  function push(b) { blocks.push(b); cur = b; }

  function ctxSnapshot() {
    var c = {};
    for (var k in stack) if (stack[k]) c[k] = stack[k];
    return c;
  }

  for (i = 0; i < lines.length; i++) {
    var raw = lines[i], line = raw.trim();
    if (!line) { if (cur) cur.lines.push(''); continue; }

    /* front matter: swallow until the first real marker */
    if (!frontDone) {
      if (RE_LONG_TITLE.test(line) || RE_ENACTING.test(line) || RE_PREAMBLE.test(line)) continue;
    }

    /* illustrations: (a) inside them is not a paragraph ladder */
    if (RE_ILLUSTR.test(line)) { inIllustration = true; if (cur) cur.lines.push(line); continue; }
    if (inIllustration && (RE_SUBSEC.test(line) || /^\s*\d{1,3}\./.test(line))) inIllustration = false;

    var matched = null, mk = null, gm = null;
    for (j = 0; j < cfg.markers.length; j++) {
      mk = cfg.markers[j];
      if (mk.annexOnly && zone !== 'annex') continue;
      if (inIllustration && mk.leaf) continue;
      if (sawArticle && mk.leaf && mk.label === 'section') continue;
      gm = line.match(mk.re);
      if (gm) { matched = mk; break; }
    }

    if (matched) {
      var g = gm.filter(function (x, idx) { return idx > 0; });
      var markerTok = null, title = '', body = '', suffix = '';

      if (matched.gulfArticle) {
        markerTok = gm[1]; suffix = gm[2] || ''; body = gm[3] || '';
      } else if (matched.runIn) {
        markerTok = gm[1]; title = gm[2] || ''; body = gm[3] || '';
      } else if (matched.mode === 'module') {
        markerTok = gm[1] + ' ' + gm[2]; suffix = gm[3] || ''; body = gm[4] || '';
      } else if (matched.mode === 'code') {
        markerTok = gm[1] + ' ' + gm[2] + '.' + gm[3]; body = gm[4] || '';
      } else if (matched.wordFirst) {
        markerTok = (gm[2] || '').trim(); title = (gm[3] || '').trim();
        if (!markerTok) markerTok = String(zoneSeq + 1);
      } else if (matched.inlineBody) {
        markerTok = gm[1]; body = gm[2] || '';
      } else if (matched.noMarker) {
        markerTok = gm[1]; title = gm[1];
      } else if (matched.label === 'annex' && cfg.rollup) {
        markerTok = gm[1]; suffix = gm[2] || ''; title = gm[3] || '';
      } else {
        /* generic: first defined capture = marker, remainder = title/body */
        markerTok = gm[1] != null ? gm[1] : (gm[2] != null ? gm[2] : '');
        if (gm[2] != null && gm[1] == null) markerTok = gm[2];
        var tail = g.slice(g.indexOf(markerTok) + 1).filter(Boolean);
        title = tail.length ? tail[tail.length - 1] : '';
      }

      if (matched.strictHeading && !isStandaloneHeading(line)) {
        if (cur) cur.lines.push(line);
        continue;
      }

      if (matched.leaf && looksLikeNoiseTitle(title || body)) {
        if (cur) cur.lines.push(line);
        continue;
      }

      frontDone = true;
      if (matched.leaf && matched.label === 'Article') sawArticle = true;

      /* "36. In this Part, ... —" : that is body, not a heading */
      if (matched.leaf && title && !matched.runIn && !matched.mode &&
          (title.length > 70 || /[.;:,\u2014-]$/.test(title.trim()) ||
           /\(\d+[A-Z]?\)/.test(title))) {
        body = title; title = '';
      }

      /* heading-above: "Citation, commencement and revocation" / "1. (1) These ..." */
      if (matched.leaf && !title && cur && cur.lines.length && opts.headingAbove !== false) {
        var prev = cur.lines[cur.lines.length - 1];
        if (prev && prev.length <= 110 && /^[A-Z\u201C"(]/.test(prev) &&
            !/[.;:,]$/.test(prev) && !/^\(/.test(prev) && /[a-z]/.test(prev)) {
          title = prev; cur.lines.pop();
          while (cur.lines.length && !cur.lines[cur.lines.length - 1]) cur.lines.pop();
        }
      }

      if (matched.zone) {
        zone = matched.zone;
        zoneSeq++;
        zoneKey = (matched.cap || 'ZONE') + ' ' + (markerTok || zoneSeq);
      }

      /* clear deeper context */
      for (var k in stack) if (Number(k) >= matched.depth) delete stack[k];
      if (!matched.leaf) {
        stack[matched.depth] = { label: matched.label, marker: markerTok, title: title };
      }

      push({
        kind: matched.leaf ? 'leaf' : 'container',
        label: matched.label,
        depth: matched.depth,
        marker: markerTok == null ? '' : String(markerTok).trim(),
        suffix: (suffix || '').trim(),
        title: (title || '').trim(),
        mode: matched.mode || null,
        zone: zone,
        zoneKey: zoneKey,
        ctx: ctxSnapshot(),
        leafUnit: (matched.leaf && leafUnit) ? leafUnit : null,
        lines: body ? [body.trim()] : []
      });
      continue;
    }

    /* not a marker -> content of the current block */
    if (!cur) {
      push({ kind: 'leaf', label: 'preamble', depth: 9, marker: '', suffix: '', title: '',
             zone: zone, zoneKey: zoneKey, ctx: {}, lines: [], preamble: true });
    }
    cur.lines.push(line);
  }

  /* tag special content lines for downstream consumers */
  for (i = 0; i < blocks.length; i++) {
    var b = blocks[i], tags = {};
    for (j = 0; j < b.lines.length; j++) {
      var L = b.lines[j];
      if (RE_PROVISO.test(L)) tags.proviso = true;
      if (RE_EXPLANATION.test(L)) tags.explanation = true;
      if (RE_ILLUSTR.test(L)) tags.illustration = true;
      if (RE_NOTE_AU.test(L)) tags.note = true;
      if (RE_PENALTY_AU.test(L)) tags.penalty = true;
      if (RE_IE_DEG.test(L)) tags.degree = true;
      if (RE_REPEALED.test(L)) tags.repealed = true;
    }
    b.tags = tags;
  }
  return blocks;
}

/* ============ STAGE 3 · render rows ============ */

/* Pass 2 — blocks -> { article, contenu } rows. */

var LEAF_PREFIX = {
  section: 'Section', Article: 'Article', clause: 'Clause', subclause: 'Clause',
  annexclause: '', rule: 'Rule', paragraph: '', block: ''
};

/* Enumeration openers - any of these starts a new contenu paragraph. */
var ENUM_RES = [
  /^\s*\((\d{1,3}[A-Z]{0,2}|[a-z]{1,3}|[ivxlcdm]{1,8}|[A-Z]{1,3})\)\s*\S/,
  /^\s*([a-z]{1,2})\)\s*\S/,                    // ISO list style  a) b)
  /^\s*(\d{1,3})\.\s+\S/,                       // Gulf clause     1.
  /^\s*([a-z])\.\s+\S/,                          // Gulf item       a.
  /^\s*(\d{1,2})\s*[\u00B0\u00BA]\s*\S/,        // Irish constitution 1deg
  /^\s*["\u201C][^"\u201D\n]{1,90}["\u201D]\s*(?:,|\(|means\b|has the meaning|includes\b|shall\b)/,  // "term" means ...
  /^\s*(?:Provided\s+(?:that|further|also)|Explanation\s*\d*\s*[.:\u2014-]|Note\s*\d*\s*:|Penalty\s*:)/i
];
function startsEnum(line) {
  for (var i = 0; i < ENUM_RES.length; i++) if (ENUM_RES[i].test(line)) return true;
  return false;
}

/* Split a leaf's text into rows: one per enumerated item or prose paragraph. */
function explodeParagraphs(lines) {
  var out = [], cur = [], i, L;
  for (i = 0; i < lines.length; i++) {
    L = lines[i];
    if (!L.trim()) { if (cur.length) { out.push(cur.join('\n')); cur = []; } continue; }
    if (startsEnum(L) && cur.length) { out.push(cur.join('\n')); cur = []; }
    cur.push(L);
  }
  if (cur.length) out.push(cur.join('\n'));
  return out.filter(function (x) { return x.trim(); });
}

function withTitle(label, b, opts) {
  if (!opts || opts.articleStyle !== 'source') return label;
  return b.title ? label + ' ' + b.title : label;
}

function articleLabel(b, family, opts) {
  var lbl = b.label, m = b.marker;
  var inSched = b.zone === 'schedule' || b.zone === 'annex';
  var prefix = inSched && b.zoneKey && lbl !== 'schedule' && lbl !== 'annex'
             ? titleCase(b.zoneKey) + ', ' : '';

  /* ---- grouping levels: family-independent ---- */
  if (lbl === 'schedule' || lbl === 'annex') return titleCase(b.zoneKey || (lbl + ' ' + m));
  if (lbl === 'backmatter') return titleCase(m || 'Bibliography');
  if (lbl === 'part'  || lbl === 'Part')  return 'Part ' + m;
  if (lbl === 'chapter')  return 'Chapter ' + m;
  if (lbl === 'book')     return 'Book ' + m;
  if (lbl === 'division') return 'Division ' + m;
  if (lbl === 'Order')    return 'Order ' + m;
  if (lbl === 'judge')    return m;

  /* ---- leaves: family-specific ---- */
  if (family === 'en_judgment') return '[' + m + ']';

  if (family === 'en_standards_clause') {
    if (lbl === 'annexclause') return withTitle((b.zoneKey ? titleCase(b.zoneKey) + ', ' : '') + m, b, opts);
    if (lbl === 'frontclause') return m;
    return withTitle((opts && opts.articleStyle === 'source') ? m : 'Clause ' + m, b, opts);
  }

  if (family === 'en_regulatory') {
    if (b.mode === 'module' || b.mode === 'code') return withTitle(m + (b.suffix ? ' ' + b.suffix : ''), b, opts);
    return withTitle(prefix + ((opts && opts.articleStyle === 'source') ? m : 'Paragraph ' + m), b, opts);
  }

  if (family === 'en_order_rule') {
    if (b.ctx && b.ctx[1] && b.ctx[1].label === 'Order') return withTitle('Order ' + b.ctx[1].marker + ', Rule ' + m, b, opts);
    return withTitle(prefix + 'Rule ' + m, b, opts);
  }

  /* leaf inside a schedule is a paragraph of that schedule (Vol. I 5.7) */
  if (inSched && (lbl === 'section' || lbl === 'Article')) {
    if (opts && opts.articleStyle === 'source') return withTitle(prefix + m, b, opts);
    return prefix + ((opts && opts.scheduleLeaf) || 'paragraph') + ' ' + m;
  }

  var p = (opts && opts.articleStyle === 'source') ? ''
        : (b.leafUnit ? b.leafUnit
          : (LEAF_PREFIX[lbl] != null ? LEAF_PREFIX[lbl] : titleCase(lbl)));
  var suf = b.suffix ? ' ' + b.suffix : '';
  return withTitle(prefix + (p ? p + ' ' : '') + m + suf, b, opts);
}

function titleCase(s) {
  return String(s).toLowerCase().replace(/\b([a-z])/g, function (m0, c) { return c.toUpperCase(); });
}

/* Standards roll-up, ported from cn_standards with segment namespacing:
   article level = max(1, deepestLevelInGroup - 1). */
function rollupStandards(blocks) {
  var i, b, parts, top, seg = 0, high = 0, meta = [], maxDepth = {}, isDef = {};

  /* pass A - segment id + deepest level reached under each top-level clause */
  for (i = 0; i < blocks.length; i++) {
    b = blocks[i];
    if (b.label !== 'subclause' && b.label !== 'clause' && b.label !== 'annexclause') { meta.push(null); continue; }
    parts = String(b.marker).split('.');
    top = markerValue(parts[0]);
    if (parts.length >= 2 && !isNaN(top)) {
      if (top < high) { seg++; high = top; } else high = Math.max(high, top);
    }
    var tkey = seg + '|' + parts[0];
    maxDepth[tkey] = Math.max(maxDepth[tkey] || 1, parts.length);
    if (parts.length === 1 && /terms and definitions|definitions/i.test(b.title || '')) isDef[tkey] = true;
    meta.push({ seg: seg, parts: parts, tkey: tkey });
  }

  /* pass B - group by the first `level` marker components */
  var groups = [], index = {};
  for (i = 0; i < blocks.length; i++) {
    b = blocks[i];
    var m = meta[i];
    if (!m) { groups.push({ solo: b }); continue; }
    var level = Math.max(1, (maxDepth[m.tkey] || 1) - 1);
    if (isDef[m.tkey]) level = Math.max(level, 2);
    var key = m.seg + '|' + m.parts.slice(0, level).join('.');
    if (m.parts.length < level) key = m.seg + '|' + m.parts.join('.') + '|solo';
    if (!index[key]) { index[key] = { head: b, members: [], key: key }; groups.push(index[key]); }
    index[key].members.push(b);
  }
  return groups;
}

function blockText(b, opts) {
  var lines = b.lines.slice();
  if (opts && opts.includeHeadingInContenu && b.title) lines.unshift(b.title);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function toRows(blocks, family, opts) {
  opts = opts || {};
  var rows = [], i, j;
  var emitHeadings = opts.emitHeadings !== false;
  var isStandards = (family === 'en_standards_clause');

  function ctxField(b, label) {
    for (var k in b.ctx) if (b.ctx[k] && b.ctx[k].label === label) {
      return (label === 'Order' ? 'Order ' : titleCase(label) + ' ') + b.ctx[k].marker;
    }
    return '';
  }

  function emit(b, article, contenu) {
    if (!article) return;
    if (opts.explodeParagraphs && b.kind === 'leaf') {
      var parts = explodeParagraphs(String(contenu == null ? '' : contenu).split('\n'));
      if (!parts.length) parts = [''];
      for (var pi = 0; pi < parts.length; pi++) push(b, article, parts[pi], pi + 1);
      return;
    }
    push(b, article, contenu, 0);
  }

  function push(b, article, contenu, para) {
    rows.push({
      para: para,
      article: article,
      contenu: contenu == null ? '' : contenu,
      label: b.label,
      family: family,
      zone: b.zone || 'body',
      part: ctxField(b, 'part') || ctxField(b, 'Part'),
      chapter: ctxField(b, 'chapter'),
      heading: b.title || '',
      status: b.suffix || '',
      tags: Object.keys(b.tags || {}).join(',')
    });
  }

  if (isStandards && opts.standardsRollup !== false) {
    var groups = rollupStandards(blocks);
    for (i = 0; i < groups.length; i++) {
      var g = groups[i];
      if (g.solo) {
        var b0 = g.solo;
        if (b0.preamble) { if (opts.keepPreamble) emit(b0, 'Preamble', blockText(b0, opts)); continue; }
        if (b0.kind === 'container' && !emitHeadings) continue;
        emit(b0, articleLabel(b0, family, opts),
             b0.kind === 'container' ? (b0.title || blockText(b0, opts))
                                     : (blockText(b0, opts) || b0.title));
        continue;
      }
      var head = g.head, buf = [];
      for (j = 0; j < g.members.length; j++) {
        var mb = g.members[j];
        var t = blockText(mb, opts);
        var lead = (mb === head) ? (mb.title || '') : ((mb.marker + ' ' + (mb.title || '')).trim());
        var chunk = [lead, t].filter(Boolean).join('\n');
        if (chunk) buf.push(chunk);
      }
      emit(head, articleLabel(head, family, opts), buf.join('\n').trim());
    }
    return rows;
  }

  for (i = 0; i < blocks.length; i++) {
    var b = blocks[i];
    if (b.preamble) { if (opts.keepPreamble) emit(b, 'Preamble', blockText(b, opts)); continue; }

    if (b.kind === 'container') {
      /* mirrors the Chinese "第一章 总则" split: marker -> article, title -> contenu */
      if (emitHeadings) emit(b, articleLabel(b, family, opts), b.title || blockText(b, opts));
      continue;
    }

    var text = blockText(b, opts);
    if (opts.includeHeadingInContenu !== true && b.title && b.lines.length === 0) text = b.title;
    emit(b, articleLabel(b, family, opts), text);
  }
  return rows;
}

/* ============ DRIVER ============ */

/* ======================= KNOBS ======================= */
const CFG = {
  /* stage 1 — clean */
  dewrap: false,          // true only for hard-wrapped pdftotext input; Mistral reflows
  stripMarkdown: true,
  skipTOC: true,          // drop "ARRANGEMENT OF SECTIONS/REGULATIONS" front matter
  dropRepeated: true,     // drop running headers/footers by frequency
  minRepeat: 4,

  /* stage 2 — detect */
  forceClass:    null,    // primary|constitution|subsidiary|regulatory|court_rules|judgment|standard
  forceDialect:  null,    // UK|IE|AU|HK|IN|NG|ZA|AE
  forceFamily:   null,
  forceLeafUnit: null,    // Regulation|Rule|Article — else read from the instrument title
  skipFrontMatter: true,

  /* stage 3 — render */
  explodeParagraphs: true,   // one row per enumerated item / prose paragraph
  articleStyle: 'source',    // 'source'   -> "1 Citation, commencement and revocation"
                             // 'labelled' -> "Regulation 1"
  emitHeadings: true,        // Part/Chapter/Schedule rows
  standardsRollup: true,     // ISO clause roll-up: article level = max(1, deepest-1)
  keepPreamble: false,
  scheduleLeaf: 'paragraph',
  includeHeadingInContenu: false,
  dropEmpty: true
};
/* ==================================================== */

function upstreamFileName(i) {
  try { return $('0 · Prepare file (base64)').all()[i].json.fileName || ''; }
  catch (e) { return ''; }
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  /* ---- stage 1 : clean ---- */
  const raw  = recordsFromText(item.json);
  const text = cleanText(raw, CFG);

  /* ---- stage 2 : detect class, dialect, leaf unit, then split blocks ---- */
  const cls = CFG.forceClass   ? { doc_class: CFG.forceClass, scores: {} } : classifyDoc(text);
  const dia = CFG.forceDialect ? { dialect: CFG.forceDialect, scores: {} } : classifyDialect(text);
  const family   = CFG.forceFamily   || pickFamily(cls.doc_class, dia.dialect, text);
  const leafUnit = CFG.forceLeafUnit || detectLeafUnit(text, cls.doc_class);

  const stripped = applyStrippers(text, dia.dialect, cls.doc_class);
  const blocks   = toBlocks(stripped, family, Object.assign({}, CFG, { leafUnit: leafUnit }));

  /* ---- stage 3 : render { article, contenu } ---- */
  const rows   = toRows(blocks, family, CFG);
  const source = item.json.fileName || item.json.source || upstreamFileName(i);

  console.log('[parse] ' + (source || 'doc ' + i) +
              '  class=' + cls.doc_class + '  dialect=' + (dia.dialect || '-') +
              '  family=' + family + '  leaf=' + (leafUnit || 'default') +
              '  blocks=' + blocks.length + '  rows=' + rows.length);

  for (const r of rows) {
    if (CFG.dropEmpty && !r.article) continue;
    out.push({ json: {
      article:   r.article,
      contenu:   r.contenu,
      para:      r.para,
      heading:   r.heading,
      label:     r.label,
      family:    family,
      doc_class: cls.doc_class,
      dialect:   dia.dialect || '',
      zone:      r.zone,
      part:      r.part,
      chapter:   r.chapter,
      status:    r.status,
      tags:      r.tags,
      source:    source
    }});
  }
}
return out;
